import {rankFor,rankLabel} from './engine.js';
// Original code-drawn pixel character. No external image or copyrighted sprite.
export function judah(completed=0,pose='idle',caption=true){
 const rank=rankFor(completed),stage=['Novice','Student','Scholar','Scribe','Master'].indexOf(rank.name);
 const cloth=['#bba581','#547584','#304b71','#286b69','#e1d5af'][stage],shade=['#78664e','#304757','#1d2f4d','#194540','#9d906e'][stage],trim=['#78664e','#bba581','#c4ab70','#dbc492','#e7bd55'][stage];
 const label=`Judah · ${rankLabel(rank)}`;
 return `<figure class="judah judah-${pose} judah-stage-${stage}" data-rank="${rank.name}" data-degree="${rank.degree}"><svg viewBox="0 0 64 112" role="img" aria-label="${label}" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg"><ellipse cx="32" cy="108" rx="23" ry="3" fill="#080e1d" opacity=".5"/><g class="judah-body"><path fill="#1b1720" d="M22 82h9v23H19v-6h3zm12 0h9l3 23H33z"/><path fill="#49362d" d="M18 102h14v6H16v-4zm15 0h15v6H33z"/><path fill="${shade}" d="M19 39h25l6 51H14z"/><path fill="${cloth}" d="M22 38h19l4 49H19z"/><path fill="${shade}" d="M18 41h7l-7 25-8-3zm23 0h6l8 22-8 3z"/><path fill="#70432f" d="M10 61h8v12h-6v-3h-2zm37 0h8v10h-2v3h-6z"/><path fill="#a66c49" d="M11 62h4v8h-3zm38 0h4v8h-4z"/><path fill="${trim}" d="M19 61h25v4H19z"/><path fill="${shade}" d="M28 65h4v20h-4z"/>
 ${stage>0?`<path fill="${trim}" d="M22 40h5l15 22-4 3z"/>`:''}
 ${stage>1?`<path fill="#382e3a" d="M45 60h10v17H43V62z"/><path fill="#e3d2a1" d="M45 63h8v11h-8z"/><path fill="#8d583b" d="M44 66h5v5h-5z"/>`:''}
 ${stage>2?`<path fill="${shade}" d="M16 41l7-3-3 45-7 5zm25-3 8 4 2 44-8-3z"/><path fill="${trim}" d="M20 39h2l-4 44h-2zm22 0h2l3 44h-2z"/>`:''}
 ${stage===4?`<path fill="#514269" d="M17 39h8l7 9 7-9h8l-4 20-11-7-11 7z"/><path fill="${trim}" d="m23 39 9 10 9-10h3L32 53 20 39z"/>${Array.from({length:Math.min(8,rank.degree)},(_,i)=>`<rect x="${22+i*3}" y="85" width="2" height="2" fill="${trim}"/>`).join('')}`:''}
 <path fill="#70432f" d="M27 28h11v14l-6 5-6-6z"/><path fill="#19171e" d="M21 8h23v26H20V15z"/><path fill="#8d583b" d="M25 14h15v19l-4 6h-8l-5-6V20z"/><path fill="#ae734c" d="M26 16h12v15l-4 5h-6l-3-7z"/><path fill="#70432f" d="M24 24h3v8h-3zm13-1h3v10h-3z"/><path fill="#1c1920" d="M25 22h5v2h-5zm10 0h5v2h-5z"/><path fill="#ddd0ae" d="M27 24h2v1h-2zm9 0h2v1h-2z"/><path fill="#70432f" d="M32 24h2v6h-3v-2h1z"/><path fill="#3a2825" d="M28 32h9v2h-9zm-1 2h3v3h5v-3h3v4l-5 3-6-4z"/>
 <g fill="#201b23"><path d="M23 10h4v18h-4zm4-3h4v12h-4zm5 0h4v11h-4zm5 1h4v13h-4zm5 3h4v25h-4zm-23 5h4v23h-4zm1 16h4v12h-4zm21 0h5v12h-5z"/></g><path stroke="#3c2c2c" stroke-width="1" d="M24 13v10m5-13v7m5-7v6m5-4v7m5-3v18M21 21v15"/></g></svg>${caption?`<figcaption><b>JUDAH</b><span>${rankLabel(rank)}</span></figcaption>`:''}</figure>`;
}
export function judahJourney(completed){return `<section class="judah-journey"><h2>Judah’s journey</h2><p>An original companion who advances with your earned rank. Clothing previews below unlock through cleared levels.</p><div class="judah-ranks">${[0,5,15,30,50].map(n=>`<article class="${completed>=n?'earned':'unearned'}">${judah(n)}<small>${completed>=n?'EARNED':`PREVIEW · CLEAR ${n} LEVELS`}</small></article>`).join('')}</div><p>Master degrees retain the honorable mantle, add embroidered marks up to eight, and display the earned degree.</p></section>`}
